<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Blaster 95</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: #000; }
  canvas { display: block; width: 100vw; height: 100vh; cursor: crosshair; }
</style>
</head>
<body>
<canvas id="game"></canvas>
<script>
"use strict";
// Balloon Blaster 95 — single-file archery game.
// Aim with mouse, hold to draw the bow (power), release to shoot.
// Pop balloons to score. Miss 3 arrows (or let 5 balloons escape) and you lose.

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
let W = 0, H = 0, DPR = 1;

function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  canvas.width = Math.floor(W * DPR);
  canvas.height = Math.floor(H * DPR);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
}
window.addEventListener("resize", resize);
resize();

// ---------- Audio (WebAudio, no assets) ----------
let actx = null;
function audio() {
  if (!actx) {
    try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { actx = null; }
  }
  if (actx && actx.state === "suspended") actx.resume();
  return actx;
}
function blip(freq, dur, type, vol, slideTo) {
  const a = audio(); if (!a) return;
  const t = a.currentTime;
  const o = a.createOscillator(), g = a.createGain();
  o.type = type || "square";
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t + dur);
  g.gain.setValueAtTime(vol || 0.15, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(a.destination);
  o.start(t); o.stop(t + dur + 0.02);
}
function noiseBurst(dur, vol, hp) {
  const a = audio(); if (!a) return;
  const t = a.currentTime;
  const len = Math.max(1, Math.floor(a.sampleRate * dur));
  const buf = a.createBuffer(1, len, a.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = a.createBufferSource(); src.buffer = buf;
  const g = a.createGain(); g.gain.value = vol || 0.2;
  let node = src;
  if (hp) { const f = a.createBiquadFilter(); f.type = "highpass"; f.frequency.value = hp; node.connect(f); node = f; }
  node.connect(g); g.connect(a.destination);
  src.start(t);
}
const sfx = {
  draw: (p) => blip(120 + p * 220, 0.05, "sawtooth", 0.05),
  shoot: () => { noiseBurst(0.12, 0.25, 800); blip(300, 0.12, "triangle", 0.12, 90); },
  pop: () => { noiseBurst(0.08, 0.35, 1500); blip(880, 0.09, "square", 0.18, 1400); },
  miss: () => blip(160, 0.25, "sawtooth", 0.12, 60),
  escape: () => blip(500, 0.3, "triangle", 0.1, 200),
  win: () => { [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => blip(f, 0.18, "square", 0.15), i * 110)); },
  lose: () => { [392, 330, 262, 196].forEach((f, i) => setTimeout(() => blip(f, 0.22, "sawtooth", 0.12), i * 140)); },
  click: () => blip(700, 0.06, "square", 0.12),
};

// ---------- State ----------
const STATE = { MENU: 0, PLAYING: 1, WIN: 2, LOSE: 3 };
let state = STATE.MENU;
let score = 0;
let misses = 0;          // arrows that hit nothing
let escapes = 0;         // balloons that floated away
const MAX_MISSES = 3, MAX_ESCAPES = 5, TARGET_SCORE = 50;

const mouse = { x: W / 2, y: H / 3, down: false };
let drawPower = 0;       // 0..1 while holding
const DRAW_SPEED = 1.4;  // per second
const MAX_DRAW = 1.0;

const archer = { x: 0, y: 0 }; // recomputed on layout
function layoutArcher() { archer.x = Math.max(70, W * 0.12); archer.y = H - 90; }
layoutArcher();
window.addEventListener("resize", layoutArcher);

